import 'dart:async';
import 'dart:convert';
import 'dart:js_interop';
import 'dart:js_interop_unsafe';

import 'package:dwi/dwi.dart';

// Generated by `dart run dwi_builder:dwi build`. Deliberately absent in a fresh
// checkout: the first ordinary Flutter build is expected to fail on this import
// until the DWI pre-build command has run.
import 'dwi_tasks.g.dart';

@JS('document')
external JSObject get _document;

@JS('fetch')
external JSPromise<JSObject> _fetch(JSString url);

extension type _FetchResponse(JSObject _) implements JSObject {
  external JSPromise<JSString> text();
}

/// Fetches the served worker script so the fixture proves the asset is present
/// and reachable at the deployment mount, not just that a task eventually ran.
Future<int> _workerAssetBytes(String path) async {
  try {
    final response = _FetchResponse(await _fetch(path.toJS).toDart);
    final text = await response.text().toDart;
    return text.toDart.length;
  } catch (_) {
    return -1;
  }
}

void _finish(Map<String, Object?> result) {
  _document.setProperty(
    'title'.toJS,
    base64Encode(utf8.encode(jsonEncode(result))).toJS,
  );
}

/// Release builds minify package type names, so classify by `is` rather than by
/// `runtimeType.toString()`.
String _classify(Object error) {
  if (error is DwiRemoteException) return 'DwiRemoteException';
  if (error is DwiUnknownTaskException) return 'DwiUnknownTaskException';
  if (error is DwiTimeoutException) return 'DwiTimeoutException';
  if (error is DwiStartupException) return 'DwiStartupException';
  if (error is DwiUnsupportedException) return 'DwiUnsupportedException';
  if (error is DwiSerializationException) return 'DwiSerializationException';
  if (error is DwiResultTypeException) return 'DwiResultTypeException';
  return 'OTHER:${error.runtimeType}';
}

Future<void> main() async {
  final result = <String, Object?>{};
  try {
    await Dwi.configure(const DwiConfig());
    result['capabilityBackend'] = (await Dwi.capabilities()).backend.name;
    result['workerAssetBytes'] = await _workerAssetBytes(
      DwiConfig.defaultWorkerScript,
    );

    // 1. Generated typed task through the proxy.
    result['typed'] = await DwiTasks.counter(0);

    // 2. One persistent handle keeps worker-local state across calls. This is
    // the published 0.5.3 API (`using`/`runFresh` are unreleased); the
    // checkout-consumer fixture covers those separately.
    final worker = await DwiWorker.spawn();
    try {
      result['handle'] = <int>[
        await worker.run<int>('counter', 0),
        await worker.run<int>('counter', 0),
      ];
    } finally {
      await worker.close();
    }

    // 3. Channel exchange on a dedicated handle.
    final channelWorker = await DwiWorker.spawn();
    final channel = await channelWorker.openChannel('progress');
    final reply = channel.messages.first;
    await channelWorker.run<String>('channelEcho', 'progress');
    await channel.send('ping');
    result['channel'] = await reply.timeout(const Duration(seconds: 5));
    await channelWorker.close();

    // 4. Typed remote error, then another successful pooled call.
    try {
      await DwiTasks.boom('x');
      result['remote'] = 'NO_ERROR';
    } catch (error) {
      result['remote'] = _classify(error);
    }
    result['afterError'] = await DwiTasks.echo('ok');
  } catch (error, stack) {
    result['fatal'] = '$error';
    result['fatalStack'] = '$stack';
  }
  _finish(result);
}
